-- UNSUPPORTED: nurse staffing / staffed hours (no staffing, schedule-shift, timecard or payroll stream). Diagnostic returns prerequisite_available = 0 when no such stream (and no such field) has been received.
SELECT CASE WHEN EXISTS (SELECT 1 FROM records WHERE stream LIKE '%staff%' OR stream LIKE '%shift%' OR stream LIKE '%timecard%' OR stream LIKE '%payroll%' OR stream LIKE '%workforce%') THEN 1 ELSE 0 END AS prerequisite_available;
